(561103, 56669, 2158, '<td valign="top">With the white background I find it difficult to see where the rabbit ends and where the background begins.</td>', 'With the white background I find it difficult to see where the rabbit ends and where the background begins.', '2004-01-28 17:56:21.000000', NULL, 1),
(561106, 56662, 16352, '<td valign="top">Not what I was expecting - Nice fun picture. From a critical point of view I think they are too central and that panning would have blurred the background and let the background given the impression of speed and kept more focus on the pigs "HOWEVER" This is clearly a grabbed shot and you don''t get the opportunity to give it another go so I think other things are needed to LIFT the picture, ones which can be done in software and still remain within the rules of the challenge.<br/>I fiddled with it in photoshop, just to try and give it a "lift".<br/>First thing was a change to black and white and up the contrast - this enhanced the differences in the pigs colours/markings.<br/>secondly, as there are 3 parralel fence rails which the pigs are running parralel with next to a line of snow - I used this to lead the eye through the photo from right to left.<br/>3:- Crop the top of the picture right to the top of the top of the top right hand side of the fence rail (that was a mouthful.<br/>4:. That has now left a lot of foreground and the line of snow goes in the wrong direction. So crop the bottom almost up to the bottom of the left pigs foot.<br/>---<br/>This leaves a long thin picture but as all the lines are parralel I think it works.<br/>---<br/>All the elements of a good picture of there, I think they just need finding within the picture and isolating. <br/>David<br/> <br/> <br/> <br/></td>', 'Not what I was expecting - Nice fun picture. From a critical point of view I think they are too central and that panning would have blurred the background and let the background given the impression of speed and kept more focus on the pigs "HOWEVER" This is clearly a grabbed shot and you don''t get the opportunity to give it another go so I think other things are needed to LIFT the picture, ones which can be done in software and still remain within the rules of the challenge.I fiddled with it in photoshop, just to try and give it a "lift".First thing was a change to black and white and up the contrast - this enhanced the differences in the pigs colours/markings.secondly, as there are 3 parralel fence rails which the pigs are running parralel with next to a line of snow - I used this to lead the eye through the photo from right to left.3:- Crop the top of the picture right to the top of the top of the top right hand side of the fence rail (that was a mouthful.4:. That has now left a lot of foreground and the line of snow goes in the wrong direction. So crop the bottom almost up to the bottom of the left pigs foot.---This leaves a long thin picture but as all the lines are parralel I think it works.---All the elements of a good picture of there, I think they just need finding within the picture and isolating. David   ', '2004-01-28 17:57:21.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(561113, 56751, 16352, '<td valign="top">Very beautiful dog and you have retained the texture of the hair perfectly. Eyes have a beautiful catchlight, subtle and not overpowering. The collar really does look like stainless steel.<br/>I am sure you have had comments on the background! <br/>What a shame. Especially when the dog looks like he is happy to pose (my dog loves the camera and will sit for ages, move head left - hold - right hold - head up - hold etc.)<br/>If this were my picture I would definatly edit the background and get it printed.<br/>David<br/></td>', 'Very beautiful dog and you have retained the texture of the hair perfectly. Eyes have a beautiful catchlight, subtle and not overpowering. The collar really does look like stainless steel.I am sure you have had comments on the background! What a shame. Especially when the dog looks like he is happy to pose (my dog loves the camera and will sit for ages, move head left - hold - right hold - head up - hold etc.)If this were my picture I would definatly edit the background and get it printed.David', '2004-01-28 18:02:26.000000', NULL, 1),
(561119, 56750, 16352, '<td valign="top">Really nice calendar shot. The only thing is that angles (angled horizons) tend to create a sense of excitment, It is a psychological phenomena) rather like the old Batman style of filming.<br/>I think that is what has gone wrong in the picture.<br/>I know the horse does not look right when the picture is rotated to level the background, I tried in photoshop - so this is one of those times when you need to have in your minds ete when taking the shot - "what is happening outside the main subject".<br/>It''s a shame because it is beautifully exposed. It needed a walk-around to try and find a different angle. it''s the classic case of taking a beautiful landscape and then on looking at the picture finding a huge litter bin right in the foregound!<br/>Getting the exposure of the horse as good as that in snow is an achievement in itself.<br/>David<br/></td>', 'Really nice calendar shot. The only thing is that angles (angled horizons) tend to create a sense of excitment, It is a psychological phenomena) rather like the old Batman style of filming.I think that is what has gone wrong in the picture.I know the horse does not look right when the picture is rotated to level the background, I tried in photoshop - so this is one of those times when you need to have in your minds ete when taking the shot - "what is happening outside the main subject".It''s a shame because it is beautifully exposed. It needed a walk-around to try and find a different angle. it''s the classic case of taking a beautiful landscape and then on looking at the picture finding a huge litter bin right in the foregound!Getting the exposure of the horse as good as that in snow is an achievement in itself.David', '2004-01-28 18:11:16.000000', NULL, 1),
(561129, 56635, 16352, '<td valign="top">Really good interpretation - Like it very much - it says so much but shows so little and the puzzle of how it got round the tree is great.<br/>I have concerns relating to exposure  and whether it may have been a good idea to have held a reflector to one side, but this is one of those instances where the picture itself - takes precedance over the technical aspects.<br/>Truly wonderful<br/>David<br/></td>', 'Really good interpretation - Like it very much - it says so much but shows so little and the puzzle of how it got round the tree is great.I have concerns relating to exposure  and whether it may have been a good idea to have held a reflector to one side, but this is one of those instances where the picture itself - takes precedance over the technical aspects.Truly wonderfulDavid', '2004-01-28 18:15:37.000000', NULL, 1),
(561136, 56545, 16352, '<td valign="top">Should this have been here or in "painted with light". Beautifully lit.<br/>My one concern in the whole picture is the flame. It appears to be coming from the wrong place. I edited it out in photoshop and the dragon was strong enough to stand on its own merit. perhaps if the flame had been further away from the head?<br/>Still excellent and meanacing.<br/>David<br/></td>', 'Should this have been here or in "painted with light". Beautifully lit.My one concern in the whole picture is the flame. It appears to be coming from the wrong place. I edited it out in photoshop and the dragon was strong enough to stand on its own merit. perhaps if the flame had been further away from the head?Still excellent and meanacing.David', '2004-01-28 18:21:21.000000', NULL, 1),
(561191, 56588, 6600, '<td valign="top">Good lighting and exposure, neat effects. - Where is the forked tongue?</td>', 'Good lighting and exposure, neat effects. - Where is the forked tongue?', '2004-01-28 19:11:08.000000', NULL, 1),
(561196, 56561, 6600, '<td valign="top">Overexposed hotspots detract, composition is ok, I personally do not care for the applied filter (for this shot).</td>', 'Overexposed hotspots detract, composition is ok, I personally do not care for the applied filter (for this shot).', '2004-01-28 19:16:24.000000', NULL, 1),
(561205, 56564, 6600, '<td valign="top">The EYE is an attention getter (almost looks out of place, is this a rare eye color?).  Nice composition and color.  Sharpness is good, body of horse appears  underexposed (on my monitor).  Good DOF, beautiful animal.</td>', 'The EYE is an attention getter (almost looks out of place, is this a rare eye color?).  Nice composition and color.  Sharpness is good, body of horse appears  underexposed (on my monitor).  Good DOF, beautiful animal.', '2004-01-28 19:25:36.000000', NULL, 1),
(561216, 56718, 6600, '<td valign="top">I don''t know why, but when I view this I think of the Jackalope (from the Tonight Show - Leno).  Or maybe even Caddy Shack.  Oh well......  Good color, exposure, focus, etc., kind of funny.</td>', 'I don''t know why, but when I view this I think of the Jackalope (from the Tonight Show - Leno).  Or maybe even Caddy Shack.  Oh well......  Good color, exposure, focus, etc., kind of funny.', '2004-01-28 19:30:47.000000', NULL, 1),
(561243, 56702, 10268, '<td valign="top">Great capture.<br/> <br/>I''ve tried taking pictures of my friend''s chicked, and I can  never get it to stay still.</td>', 'Great capture. I''ve tried taking pictures of my friend''s chicked, and I can  never get it to stay still.', '2004-01-28 19:59:45.000000', NULL, 1),
(561377, 56540, 12733, '<td valign="top">It takes more imagination than I''ve got to make much of a dragon out of this. Nice try.</td>', 'It takes more imagination than I''ve got to make much of a dragon out of this. Nice try.', '2004-01-28 22:08:19.000000', NULL, 1),
(561380, 56611, 12733, '<td valign="top">Great mood lighting. Does the symbol on his face represent the dragon???</td>', 'Great mood lighting. Does the symbol on his face represent the dragon???', '2004-01-28 22:09:26.000000', NULL, 1),
(561384, 56573, 12733, '<td valign="top">They''re kind of cute, but given that this was an advanced editing challenge, I think rmoving the white spots at the back of the shot would have improved it greatly.</td>', 'They''re kind of cute, but given that this was an advanced editing challenge, I think rmoving the white spots at the back of the shot would have improved it greatly.', '2004-01-28 22:11:09.000000', NULL, 1),
(561386, 56688, 12733, '<td valign="top">Cute dog, nicely composed and lighted. What kind is it??</td>', 'Cute dog, nicely composed and lighted. What kind is it??', '2004-01-28 22:12:11.000000', NULL, 1),
(561398, 56545, 12733, '<td valign="top">This is one fierce looking dragon. What is the apparent flame pouring out of its mouth???</td>', 'This is one fierce looking dragon. What is the apparent flame pouring out of its mouth???', '2004-01-28 22:14:32.000000', NULL, 1),
(561405, 56662, 12733, '<td valign="top">The pigs are cute, but I think you need a tighter crop and sharper focus to bring out the best in them.</td>', 'The pigs are cute, but I think you need a tighter crop and sharper focus to bring out the best in them.', '2004-01-28 22:15:50.000000', NULL, 1),
(561407, 56752, 12733, '<td valign="top">A cute dog and a well executed closeup.</td>', 'A cute dog and a well executed closeup.', '2004-01-28 22:16:54.000000', NULL, 1),
(561408, 56642, 12733, '<td valign="top">Very interesting shot, nice composition and great use of shadow. This is not a real snake, is it?</td>', 'Very interesting shot, nice composition and great use of shadow. This is not a real snake, is it?', '2004-01-28 22:18:37.000000', NULL, 1),
(561414, 56687, 12733, '<td valign="top">Very nice capture of the sheep. The background is kind of busy, and the sheep has two unicorn horns (branches) apparently jutting out of his forehead.</td>', 'Very nice capture of the sheep. The background is kind of busy, and the sheep has two unicorn horns (branches) apparently jutting out of his forehead.', '2004-01-28 22:21:49.000000', NULL, 1),
(561420, 56676, 12733, '<td valign="top">That''s a cute monkey. The colors look strange - is that really green on its back or the reflections from the foliage behind it?</td>', 'That''s a cute monkey. The colors look strange - is that really green on its back or the reflections from the foliage behind it?', '2004-01-28 22:24:14.000000', NULL, 1),
(561423, 56654, 12733, '<td valign="top">It''s a pretty shot: i''ll forgive the bad pun. The dog looks as though he''s trying to make some kind of a statement.</td>', 'It''s a pretty shot: i''ll forgive the bad pun. The dog looks as though he''s trying to make some kind of a statement.', '2004-01-28 22:26:07.000000', NULL, 1),
(561426, 56745, 12733, '<td valign="top">Very nice catch. I''m surprised there aren''t more photos from New Year parades in the Chinese communities across the country.</td>', 'Very nice catch. I''m surprised there aren''t more photos from New Year parades in the Chinese communities across the country.', '2004-01-28 22:28:28.000000', NULL, 1),
(561429, 56739, 12733, '<td valign="top">I can see lots of scales, but the composition makes it difficult to really identify the snake.</td>', 'I can see lots of scales, but the composition makes it difficult to really identify the snake.', '2004-01-28 22:30:00.000000', NULL, 1),
(561435, 56532, 12733, '<td valign="top">I think the processing is overdone; the essence of the dog is lost in the extreme posterization.</td>', 'I think the processing is overdone; the essence of the dog is lost in the extreme posterization.', '2004-01-28 22:31:37.000000', NULL, 1),
(561437, 56621, 12733, '<td valign="top">A cute rabbit and a nice, clean composition.</td>', 'A cute rabbit and a nice, clean composition.', '2004-01-28 22:32:45.000000', NULL, 1),
(561442, 56608, 12733, '<td valign="top">Four of almost any animal lined up like that would look menacing, but not sheep. Cute shot, and I think black and white was a good choice.</td>', 'Four of almost any animal lined up like that would look menacing, but not sheep. Cute shot, and I think black and white was a good choice.', '2004-01-28 22:34:17.000000', NULL, 1),
(561448, 56730, 12733, '<td valign="top">A sharp looking dragon, but the background is very busy, and it takes a bit of looking to pich the dragon out of its surroundings.</td>', 'A sharp looking dragon, but the background is very busy, and it takes a bit of looking to pich the dragon out of its surroundings.', '2004-01-28 22:36:55.000000', NULL, 1),
(561456, 56737, 12733, '<td valign="top">Interesting background and effective back lighting show this dragon off well.</td>', 'Interesting background and effective back lighting show this dragon off well.', '2004-01-28 22:41:16.000000', NULL, 1),
(561464, 56651, 12733, '<td valign="top">Looks like it has blood on its teeth. Is this the color or the lighting or post processing? It''s quite effective, whatever.</td>', 'Looks like it has blood on its teeth. Is this the color or the lighting or post processing? It''s quite effective, whatever.', '2004-01-28 22:43:51.000000', NULL, 1),
(561469, 56613, 12733, '<td valign="top">With all the fake dragons in this challenge, it''s great to see a real one. He has the most amazing colors. I''d have liked a bit sharper depth of field, particularly on that foreground paw.</td>', 'With all the fake dragons in this challenge, it''s great to see a real one. He has the most amazing colors. I''d have liked a bit sharper depth of field, particularly on that foreground paw.', '2004-01-28 22:45:54.000000', NULL, 1),
(561475, 56677, 12733, '<td valign="top">Nice detail - it looks almost like a colored pencil sketch. Is this really ice?</td>', 'Nice detail - it looks almost like a colored pencil sketch. Is this really ice?', '2004-01-28 22:47:56.000000', NULL, 1),
(561478, 56701, 12733, '<td valign="top">The buildings and lights are great; the dragon almost seems superfluous. Nice detail and good composition - nice shot.</td>', 'The buildings and lights are great; the dragon almost seems superfluous. Nice detail and good composition - nice shot.', '2004-01-28 22:50:10.000000', NULL, 1),
(561488, 56739, 13772, '<td valign="top">I bet it is a beautiful snake but I wish I could see more of the head. I think it would be better if I could see the natural color of the snake and not be distracted by the color of the lights on its body.</td>', 'I bet it is a beautiful snake but I wish I could see more of the head. I think it would be better if I could see the natural color of the snake and not be distracted by the color of the lights on its body.', '2004-01-28 22:56:23.000000', NULL, 1),
(561493, 56561, 13772, '<td valign="top">I like the composition of your photo but I am distracted by the hot spots around the hoarses. I wish I could see their natuarl colors. It looks like you used a photo filter on it. Nice picture!</td>', 'I like the composition of your photo but I am distracted by the hot spots around the hoarses. I wish I could see their natuarl colors. It looks like you used a photo filter on it. Nice picture!', '2004-01-28 23:00:48.000000', NULL, 1),
(561500, 56665, 13772, '<td valign="top">Beautiful animal. Very nice photo!</td>', 'Beautiful animal. Very nice photo!', '2004-01-28 23:09:05.000000', NULL, 1),
(561564, 56705, 8367, '<td valign="top">Looks like a sweet dog.  I think this shot would really look good with the background softened or blurred.</td>', 'Looks like a sweet dog.  I think this shot would really look good with the background softened or blurred.', '2004-01-29 00:08:20.000000', NULL, 1),
(561568, 56638, 8367, '<td valign="top">Great focus with the dog moving toward you. How''d you do it?</td>', 'Great focus with the dog moving toward you. How''d you do it?', '2004-01-29 00:11:52.000000', NULL, 1),
(561572, 56588, 8367, '<td valign="top">Well done. Looks real to me.</td>', 'Well done. Looks real to me.', '2004-01-29 00:14:08.000000', NULL, 1),
(561576, 56745, 8367, '<td valign="top">Great colors and subject.</td>', 'Great colors and subject.', '2004-01-29 00:18:13.000000', NULL, 1),
(561580, 56532, 8367, '<td valign="top">I like this as digital art. The pose and colors are great. The background needs to be cleaned up a bit and maybe fill in the nose.</td>', 'I like this as digital art. The pose and colors are great. The background needs to be cleaned up a bit and maybe fill in the nose.', '2004-01-29 00:21:58.000000', NULL, 1),
(561583, 56654, 8367, '<td valign="top">Beautiful capture. The background setting is perfect for a retriever.</td>', 'Beautiful capture. The background setting is perfect for a retriever.', '2004-01-29 00:25:48.000000', NULL, 1),
(561590, 56702, 8367, '<td valign="top">Great shot. Everything looks perfect.</td>', 'Great shot. Everything looks perfect.', '2004-01-29 00:32:46.000000', NULL, 1),
(561592, 56737, 8367, '<td valign="top">Great background. Good job.</td>', 'Great background. Good job.', '2004-01-29 00:33:52.000000', NULL, 1),
(561593, 56701, 8367, '<td valign="top">Very colorful and a good find for the challenge. Good job.</td>', 'Very colorful and a good find for the challenge. Good job.', '2004-01-29 00:35:30.000000', NULL, 1),
(561595, 56699, 8367, '<td valign="top">Great focus, great capture.. Let me guess...the year you were born?  I love the background.</td>', 'Great focus, great capture.. Let me guess...the year you were born?  I love the background.', '2004-01-29 00:38:51.000000', NULL, 1),
(561679, 56651, 16703, '<td valign="top">i think this picture would have been much more interesting from a different angle. may be perhaps from an angle where you see the dragons face and teh body of the dragon blurs into distance. but since i dont exactly know what the actual dragon looks like, i might be wrong...this photo seems too busy this way..</td>', 'i think this picture would have been much more interesting from a different angle. may be perhaps from an angle where you see the dragons face and teh body of the dragon blurs into distance. but since i dont exactly know what the actual dragon looks like, i might be wrong...this photo seems too busy this way..', '2004-01-29 04:09:22.000000', NULL, 1),
(561685, 56545, 7687, '<td valign="top">Great subject!  I really like the flame coming from the mouth and the blue color on the underside of the dragon''s neck.  In my opinion, this image could be improved by cropping out all the magenta/green stuff in the left half of the image and going with a vertical format...head, neck and flame only.  <br/> <br/>Just my humble opinion of course, keep up the good work!</td>', 'Great subject!  I really like the flame coming from the mouth and the blue color on the underside of the dragon''s neck.  In my opinion, this image could be improved by cropping out all the magenta/green stuff in the left half of the image and going with a vertical format...head, neck and flame only.   Just my humble opinion of course, keep up the good work!', '2004-01-29 04:38:40.000000', NULL, 1),
(561686, 56608, 7687, '<td valign="top">I really like the composition, the choice of black and white, the clarity, the exposure...umm what else do I like...well, pretty much everything. My only nitpick would be that the image seems to be cropped a bit too tightly at the top (for my taste) but that''s a minor nitpick.   I''m really glad it meets the challenge because this is a great shot, keep up the great work.</td>', 'I really like the composition, the choice of black and white, the clarity, the exposure...umm what else do I like...well, pretty much everything. My only nitpick would be that the image seems to be cropped a bit too tightly at the top (for my taste) but that''s a minor nitpick.   I''m really glad it meets the challenge because this is a great shot, keep up the great work.', '2004-01-29 04:43:16.000000', NULL, 1),
(561687, 56635, 7687, '<td valign="top">This is one of the better, more interesting entries.  It makes you think a bit, rather than just a picture of something (dog/dragon/rabbit...etc).  Great composure and exposure...the angle also adds a dimension that we rarely see.  Very nice work.</td>', 'This is one of the better, more interesting entries.  It makes you think a bit, rather than just a picture of something (dog/dragon/rabbit...etc).  Great composure and exposure...the angle also adds a dimension that we rarely see.  Very nice work.', '2004-01-29 04:49:07.000000', NULL, 1),
(561688, 56482, 7687, '<td valign="top">A very strong image, one that stands out from the rest.  Black and White is the perfect choice while the composition is first rate.  I think this is the best entry in the contest.  Congrats!</td>', 'A very strong image, one that stands out from the rest.  Black and White is the perfect choice while the composition is first rate.  I think this is the best entry in the contest.  Congrats!', '2004-01-29 04:50:16.000000', NULL, 1),
(561712, 56635, 10170, '<td valign="top">Different ... and it works.  Nice shot.</td>', 'Different ... and it works.  Nice shot.', '2004-01-29 06:28:57.000000', NULL, 1),
(561713, 56654, 10170, '<td valign="top">Magnificent dog and great shot. 9</td>', 'Magnificent dog and great shot. 9', '2004-01-29 06:31:26.000000', NULL, 1),
(561714, 56613, 10170, '<td valign="top">Gotta love these little beasties :)  I was planning the same photo in the botanical gardens here but my camera is away sick :(  Nice shot.</td>', 'Gotta love these little beasties :)  I was planning the same photo in the botanical gardens here but my camera is away sick :(  Nice shot.', '2004-01-29 06:32:32.000000', NULL, 1),
(561813, 56608, 6008, '<td valign="top">This is cute, I like it. The black and white is a good choice to give it a nice even feel, and also a harsher/docu-photograph feel. The composition is good with the slight V. It''s full of personality.</td>', 'This is cute, I like it. The black and white is a good choice to give it a nice even feel, and also a harsher/docu-photograph feel. The composition is good with the slight V. It''s full of personality.', '2004-01-29 09:57:28.000000', NULL, 1),
(561816, 56568, 6008, '<td valign="top">This has a great tone to it. The image is nicely sharp, dof is good, and I like the bones in the background. Composition is great, and the catchlights in the eyes really stand out. The horns have great texture, so does the hair/fur on the face and back.</td>', 'This has a great tone to it. The image is nicely sharp, dof is good, and I like the bones in the background. Composition is great, and the catchlights in the eyes really stand out. The horns have great texture, so does the hair/fur on the face and back.', '2004-01-29 10:01:24.000000', NULL, 1),
(561817, 56591, 6008, '<td valign="top">Good texture of the fur, nice coloring, good dof too. Interesting composition also.</td>', 'Good texture of the fur, nice coloring, good dof too. Interesting composition also.', '2004-01-29 10:05:25.000000', NULL, 1),
(561826, 56530, 772, '<td valign="top">I like the profile shot of this horse quite a bit... the angle is very nice.  The desaturation of the background also seems to work nicely here to help bring the horse out into the foreground more.  The part of this photo that looks odd to me is the fence railing at the bottom.  If there was some grain or texture on that rail to make it obvious as to what it is, I think it would be a stronger image.  In the context of this photo, it looks like it could have been edited in rather than being part of the natural image.</td>', 'I like the profile shot of this horse quite a bit... the angle is very nice.  The desaturation of the background also seems to work nicely here to help bring the horse out into the foreground more.  The part of this photo that looks odd to me is the fence railing at the bottom.  If there was some grain or texture on that rail to make it obvious as to what it is, I think it would be a stronger image.  In the context of this photo, it looks like it could have been edited in rather than being part of the natural image.', '2004-01-29 10:28:12.000000', NULL, 1),
(561942, 56655, 10705, '<td valign="top">love the shadow!!</td>', 'love the shadow!!', '2004-01-29 12:50:42.000000', NULL, 1),
(561944, 56621, 10705, '<td valign="top">this is really a cute photo ... well done!</td>', 'this is really a cute photo ... well done!', '2004-01-29 12:51:15.000000', NULL, 1),
(561945, 56717, 16316, '<td valign="top">I like how most of basics in photography have been addressed with this phote; filled frame, no distractions with background, overall composition. Your image is crisp and the red is very striking. Nicely done!</td>', 'I like how most of basics in photography have been addressed with this phote; filled frame, no distractions with background, overall composition. Your image is crisp and the red is very striking. Nicely done!', '2004-01-29 12:51:25.000000', NULL, 1),
(561952, 56655, 16316, '<td valign="top">Liked your idea and attempt. Would like it better if less of the dragon was seen (just enough to now what it was) and a deeper darker shadow.</td>', 'Liked your idea and attempt. Would like it better if less of the dragon was seen (just enough to now what it was) and a deeper darker shadow.', '2004-01-29 12:54:31.000000', NULL, 1),
(561958, 56728, 16316, '<td valign="top">Classic horse head comp nicely done. Probably would''ve done a bit more cropping to eliminate the tree line and deepened the sky.</td>', 'Classic horse head comp nicely done. Probably would''ve done a bit more cropping to eliminate the tree line and deepened the sky.', '2004-01-29 12:59:09.000000', NULL, 1),
(561962, 56749, 16316, '<td valign="top">cute...chuckle.</td>', 'cute...chuckle.', '2004-01-29 13:00:26.000000', NULL, 1),
(561968, 56704, 16316, '<td valign="top">I like the composition. Know enough what it is (and if I didn''t the soft background tells me what I need to know).</td>', 'I like the composition. Know enough what it is (and if I didn''t the soft background tells me what I need to know).', '2004-01-29 13:04:31.000000', NULL, 1),
(561971, 56635, 16316, '<td valign="top">How did he do that? (the rabbit vs. tree) Nice!</td>', 'How did he do that? (the rabbit vs. tree) Nice!', '2004-01-29 13:05:55.000000', NULL, 1),
(561974, 56495, 16316, '<td valign="top">Nice!</td>', 'Nice!', '2004-01-29 13:07:11.000000', NULL, 1),
