(562691, 56635, 16753, '<td valign="top">I <i>love</i> this. The idea, the composition, the color, everything. You were robbed! :-)</td>', 'I love this. The idea, the composition, the color, everything. You were robbed! :-)', '2004-01-30 00:26:33.000000', NULL, 0),
(562692, 56608, 6804, '<td valign="top">Congratulations on the blue ribbon Konador! I knew this would win. They look like they are singing or something. A very cool shot.</td>', 'Congratulations on the blue ribbon Konador! I knew this would win. They look like they are singing or something. A very cool shot.', '2004-01-30 00:28:14.000000', NULL, 0),
(562695, 56608, 8891, '<td valign="top">COngrats on your first BLue, Ben!  Great shot!</td>', 'COngrats on your first BLue, Ben!  Great shot!', '2004-01-30 00:30:55.000000', NULL, 0),
(562696, 56588, 14499, '<td valign="top">Sorry about the Editing comment, I though Advanced ment No Mods at all! the Wording isn''t real great. I now know "Basic" means appling to the whole picture and in "Advanced" tools can be used :)  I did love the pic by the way.</td>', 'Sorry about the Editing comment, I though Advanced ment No Mods at all! the Wording isn''t real great. I now know "Basic" means appling to the whole picture and in "Advanced" tools can be used :)  I did love the pic by the way.', '2004-01-30 00:31:02.000000', NULL, 0),
(562697, 56702, 6804, '<td valign="top">A Beautiful shot Seanachi, I love the detail and color on this one. Congratulations on 2nd place.</td>', 'A Beautiful shot Seanachi, I love the detail and color on this one. Congratulations on 2nd place.', '2004-01-30 00:31:17.000000', NULL, 0),
(562699, 56561, 14499, '<td valign="top">It did better than I thought!</td>', 'It did better than I thought!', '2004-01-30 00:33:56.000000', NULL, 0),
