INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(562724, 56562, 12332, '<td valign="top">I don''t get it.  Now - I know it''s not a top 20 because it lacks imagination, but spot-on focus, no blow-outs (over exposures), a uniformly-colored dark background, obviously meets the challenge.  And it''s bottom 5%??  Check out the photos 15-25 spots above this - out of focus, confusing elements, overexposed, camera shake, obvious use of photo manipulation software...blah, blah, blah.  I''m done with faking "studio" shots.  <br/> <br/>That said, I really do appreciate the comments - well, most of them<br/><br/><i>Message edited by author 2004-01-30 01:08:15.</i></td>', 'I don''t get it.  Now - I know it''s not a top 20 because it lacks imagination, but spot-on focus, no blow-outs (over exposures), a uniformly-colored dark background, obviously meets the challenge.  And it''s bottom 5%??  Check out the photos 15-25 spots above this - out of focus, confusing elements, overexposed, camera shake, obvious use of photo manipulation software...blah, blah, blah.  I''m done with faking "studio" shots.   That said, I really do appreciate the comments - well, most of them', '2004-01-30 01:00:54.000000', '2004-01-30 01:08:15.000000', 0),
(562742, 56590, 16266, '<td valign="top">critique club comment ....<br/> <br/>I think you have a quite strong image, with the dark deep background and engergy filled subject.  I think you chose a good background color.  The cropping on this image is VERY tight, and much too tight actually on the bottom and perhaps on the right.  The bottom white line is 1 pixel away from the bottom of the statue... which creates an akward line, and problem in the photo.  It stops the eye at an unattractive, or uninteresting spot, it also leads the eye to the edge of the photo and leaves it there stranded.  As you said, there is some white blasting in the image, and I agree.  The could be softenend with a softer light sorce, or less direct light.  Perhaps if you bounced the light off the wall before letting it hit the statue. i think the horiztonal (left right) angle is fine, and reasonably interesting, but perhaps you could play with the verticle.  Try taking the picture from a lower or higher vantage point.<br/> <br/>hope this helped.</td>', 'critique club comment .... I think you have a quite strong image, with the dark deep background and engergy filled subject.  I think you chose a good background color.  The cropping on this image is VERY tight, and much too tight actually on the bottom and perhaps on the right.  The bottom white line is 1 pixel away from the bottom of the statue... which creates an akward line, and problem in the photo.  It stops the eye at an unattractive, or uninteresting spot, it also leads the eye to the edge of the photo and leaves it there stranded.  As you said, there is some white blasting in the image, and I agree.  The could be softenend with a softer light sorce, or less direct light.  Perhaps if you bounced the light off the wall before letting it hit the statue. i think the horiztonal (left right) angle is fine, and reasonably interesting, but perhaps you could play with the verticle.  Try taking the picture from a lower or higher vantage point. hope this helped.', '2004-01-30 01:53:04.000000', NULL, 0),
(562749, 56568, 2780, '<td valign="top">Congrats Gringo, 2 ribbons in a week, nice going :)</td>', 'Congrats Gringo, 2 ribbons in a week, nice going :)', '2004-01-30 02:24:42.000000', NULL, 0),
(562755, 56608, 5158, '<td valign="top">Congrats Ben!<br/>When I saw it during the voting, I thought: that''s Ben''s because he''s right now pretty much in B&amp;W and the sheeps look very British too.<br/>Keep up the good work!</td>', 'Congrats Ben!When I saw it during the voting, I thought: that''s Ben''s because he''s right now pretty much in B&W and the sheeps look very British too.Keep up the good work!', '2004-01-30 02:59:08.000000', NULL, 0),
(562796, 56608, 1829, '<td valign="top">Ben you are a legend mate!!!  Excellent pic and a well deserved ribbon.  Congrats mate!!</td>', 'Ben you are a legend mate!!!  Excellent pic and a well deserved ribbon.  Congrats mate!!', '2004-01-30 04:31:48.000000', NULL, 0),
(562820, 56608, 6999, '<td valign="top">Very happy for you Ben - can''t believe this is your first blue ... surely you must have about 6 by now :-) Excellent shot, one of my two top picks from this challenge.</td>', 'Very happy for you Ben - can''t believe this is your first blue ... surely you must have about 6 by now :-) Excellent shot, one of my two top picks from this challenge.', '2004-01-30 05:14:52.000000', NULL, 0),
(562823, 56608, 2780, '<td valign="top">Thanks everyone :D<br/>It took me a long time to get my blue back but finally I did it! 95th time lucky! This and getting into the top fav photographers on the site were my 2 main aims, and I''ve completed them both now in the space of a few days, I''m so happy! What''s next? Hmmm I''ll have to think about that one. <br/>Thanks for all the comments and votes. I thought I might get a ribbon when I saw my score was 7.5 throughout the week, but then on the last couple of days as it dropped and dropped, I felt sure I''d get 4th place or something annoying like that (sorry mood!).<br/> <br/>Oh, another good thing about today is that I got my first picture published in a newspaper! I''m at school right now but when I get home I''ll scan it in :)<br/> <br/>Woohoo!<br/><br/><i>Message edited by author 2004-01-30 05:33:32.</i></td>', 'Thanks everyone :DIt took me a long time to get my blue back but finally I did it! 95th time lucky! This and getting into the top fav photographers on the site were my 2 main aims, and I''ve completed them both now in the space of a few days, I''m so happy! What''s next? Hmmm I''ll have to think about that one. Thanks for all the comments and votes. I thought I might get a ribbon when I saw my score was 7.5 throughout the week, but then on the last couple of days as it dropped and dropped, I felt sure I''d get 4th place or something annoying like that (sorry mood!). Oh, another good thing about today is that I got my first picture published in a newspaper! I''m at school right now but when I get home I''ll scan it in :) Woohoo!', '2004-01-30 05:23:18.000000', '2004-01-30 05:33:32.000000', 0),
(562827, 56530, 2780, '<td valign="top">Great shot shiz :) When I said order in my comment, I meant border, hehe</td>', 'Great shot shiz :) When I said order in my comment, I meant border, hehe', '2004-01-30 05:34:57.000000', NULL, 0),
(562834, 56608, 6999, '<td valign="top"><b>your critique club moment</b> <br/> <br/>Hi Ben.<br/> <br/>Very tempted to leave this blank, as there is almost definitely nothing I can constructively say about this shot. What would you have different, either in the image or the result? Only one thing that i thought immediately on seeing it, and still think on re-consideration of it, is that if one could move the second sheep from left forward a couple of paces, and to its right half a step, the balance of the composition would be improved - it almost goes without saying that this is a ridiculously small criticism (but this is the <i>Critique</i> Club)<br/> <br/>Can I think of anything else to say ... ? Black and White works for this shot for a very specific reason: I can imagine it in colour - even quite liking it so (the green grass would presumably be a satisfying colour). Removing that element brings the emphasis to a different place - the graphic element provided by the line-up of the animals: and that is where the humour is, of course: the apparently ''posed'' quality: ''OK now, everyone point your ears out''<br/> <br/>Top work, mate. <br/> <br/>Ed<br/> <br/></td>', 'your critique club moment  Hi Ben. Very tempted to leave this blank, as there is almost definitely nothing I can constructively say about this shot. What would you have different, either in the image or the result? Only one thing that i thought immediately on seeing it, and still think on re-consideration of it, is that if one could move the second sheep from left forward a couple of paces, and to its right half a step, the balance of the composition would be improved - it almost goes without saying that this is a ridiculously small criticism (but this is the Critique Club) Can I think of anything else to say ... ? Black and White works for this shot for a very specific reason: I can imagine it in colour - even quite liking it so (the green grass would presumably be a satisfying colour). Removing that element brings the emphasis to a different place - the graphic element provided by the line-up of the animals: and that is where the humour is, of course: the apparently ''posed'' quality: ''OK now, everyone point your ears out'' Top work, mate.  Ed ', '2004-01-30 05:52:15.000000', NULL, 0),
